/**
 * Children that are NOT `ON DELETE CASCADE` of a parent the run deletes —
 * they would block the parent's DELETE (NO ACTION / RESTRICT). Their pointer
 * is nulled for the user's rows before the `projects` step runs.
 *
 *   parent "projects"      → `col IN (SELECT id FROM projects WHERE user_id = <uid>)`
 *   parent "svi_accounts"  → legacy SVI accounts cascade from projects
 *                            (svi_accounts.project_id CASCADE) and are also
 *                            keyed by the user's email; their own NO ACTION
 *                            children are detached the same way.
 *
 * Rows on other users' parents are untouched.
 */
export interface ProjectDetach {
  table: string;
  column: string;
  parent: "projects" | "svi_accounts";
  note: string;
}
export const PROJECT_DETACHES: readonly ProjectDetach[] = Object.freeze([
  { table: "reseller_attributions", column: "subject_project_id", parent: "projects", note: "RESTRICT — attribution row (commission basis) kept, project pointer cleared." },
  { table: "credit_transactions", column: "project_id", parent: "projects", note: "NO ACTION — ledger kept, project pointer cleared." },
  { table: "usage_logs", column: "project_id", parent: "projects", note: "NO ACTION — ledger kept, project pointer cleared." },
  { table: "ai_runs", column: "business_id", parent: "projects", note: "NO ACTION — AI cost ledger kept." },
  { table: "reseller_credit_grants", column: "sandbox_project_id", parent: "projects", note: "NO ACTION — grant ledger kept." },
  { table: "advisor_client_roster", column: "project_id", parent: "projects", note: "NO ACTION — another advisor's roster row keeps its client name, project pointer cleared." },
  { table: "data_rooms", column: "project_id", parent: "projects", note: "NO ACTION — the user's own rooms are deleted in the same run; a room another owner attached to this project is detached." },
  { table: "funding_reports", column: "project_id", parent: "projects", note: "NO ACTION — guest / other users' reports attached to this project are detached." },
  { table: "pitchdeck_analyses", column: "project_id", parent: "projects", note: "NO ACTION — other users' analyses on this project are detached." },
  { table: "user_actions", column: "account_id", parent: "svi_accounts", note: "NO ACTION child of the legacy svi_accounts row that cascades from projects — legacy action log kept (email pseudonymised in NON_FK_EXTRAS), pointer cleared." },
  { table: "cohort_members", column: "svi_account_id", parent: "svi_accounts", note: "NO ACTION child of svi_accounts — cohort membership row kept, pointer cleared." },
]);

